//! Branch and path naming (`docs/GIT-STRATEGY.md` §2). Names are generated by Turtle Flow only,
//! never taken from agent output, and validated before use.

use crate::{GitError, Repo, Result};

pub const DEFAULT_BRANCH_PREFIX: &str = "turtle/";
const MAX_SLUG_LEN: usize = 40;

/// Lowercase ASCII slug of at most 40 characters, with separators collapsed to single dashes.
#[must_use]
pub fn slugify(title: &str) -> String {
    let mut out = String::new();
    let mut pending_dash = false;
    for c in title.chars() {
        if c.is_ascii_alphanumeric() {
            if pending_dash && !out.is_empty() {
                out.push('-');
            }
            pending_dash = false;
            out.push(c.to_ascii_lowercase());
        } else {
            pending_dash = true;
        }
    }
    out.truncate(MAX_SLUG_LEN);
    out.trim_end_matches('-').to_owned()
}

/// A job key such as `API-42`: 2–6 uppercase letters, dash, digits.
#[must_use]
pub fn is_valid_job_key(key: &str) -> bool {
    key.split_once('-').is_some_and(|(p, n)| {
        (2..=6).contains(&p.len())
            && p.bytes().all(|b| b.is_ascii_uppercase())
            && !n.is_empty()
            && n.bytes().all(|b| b.is_ascii_digit())
    })
}

/// `turtle/API-42-add-rate-limiting`. A title that slugifies to nothing yields just the key.
pub fn job_branch_name(prefix: &str, job_key: &str, title: &str) -> Result<String> {
    if !is_valid_job_key(job_key) {
        return Err(GitError::Invalid(format!("invalid job key `{job_key}`")));
    }
    if !prefix.ends_with('/')
        || !prefix[..prefix.len() - 1]
            .bytes()
            .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'-')
    {
        return Err(GitError::Invalid(format!(
            "invalid branch prefix `{prefix}`"
        )));
    }
    let slug = slugify(title);
    Ok(if slug.is_empty() {
        format!("{prefix}{job_key}")
    } else {
        format!("{prefix}{job_key}-{slug}")
    })
}

/// Validates a full branch name with Git's own rules.
pub async fn check_ref_format(repo: &Repo, branch: &str) -> Result<()> {
    if repo
        .run_bool(&["check-ref-format", "--branch", branch])
        .await?
    {
        Ok(())
    } else {
        Err(GitError::Invalid(format!(
            "`{branch}` is not a valid branch name"
        )))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn slugs_are_ascii_lowercase_and_bounded() {
        assert_eq!(
            slugify("Add per-client rate limiting!"),
            "add-per-client-rate-limiting"
        );
        assert_eq!(slugify("  --Ünïcode & spaces--  "), "n-code-spaces");
        assert_eq!(slugify("¿¡"), "");
        let long = slugify(&"word ".repeat(30));
        assert!(long.len() <= 40 && !long.ends_with('-'), "{long}");
    }

    #[test]
    fn branch_names() {
        assert_eq!(
            job_branch_name("turtle/", "API-42", "Add rate limiting").expect("valid"),
            "turtle/API-42-add-rate-limiting"
        );
        assert_eq!(
            job_branch_name("turtle/", "API-42", "???").expect("valid"),
            "turtle/API-42"
        );
        assert!(job_branch_name("turtle/", "api-42", "x").is_err());
        assert!(job_branch_name("turtle/", "API-42; rm -rf", "x").is_err());
        assert!(job_branch_name("../", "API-42", "x").is_err());
        assert!(job_branch_name("turtle", "API-42", "x").is_err());
    }

    #[test]
    fn job_keys() {
        assert!(is_valid_job_key("API-1"));
        assert!(!is_valid_job_key("A-1"));
        assert!(!is_valid_job_key("API-"));
        assert!(!is_valid_job_key("API-1x"));
    }
}
